import React, { useState, useEffect } from 'react';
import { FiUsers, FiSearch, FiX, FiPlus, FiCheck, FiLoader } from 'react-icons/fi';
import api from '../services/api';

const GroupChat = ({ onClose }) => {
  const [users, setUsers] = useState([]);
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [groupName, setGroupName] = useState('');
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    fetchUsers();
  }, []);

  useEffect(() => {
    const filtered = users.filter(user => 
      user.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredUsers(filtered);
  }, [searchTerm, users]);

  const fetchUsers = async () => {
    try {
      const res = await api.get('/friendship/users');
      setUsers(res.data);
      setFilteredUsers(res.data);
    } catch (error) {
      console.error('Error fetching users:', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleUserSelection = (user) => {
    setSelectedUsers(prev => {
      const isSelected = prev.some(u => u.id === user.id);
      if (isSelected) {
        return prev.filter(u => u.id !== user.id);
      } else {
        return [...prev, user];
      }
    });
  };

  const createGroupChat = async (e) => {
    e.preventDefault();

    if (!groupName.trim()) {
      alert('Veuillez entrer un nom pour le groupe');
      return;
    }

    if (selectedUsers.length === 0) {
      alert('Veuillez sélectionner au moins un membre');
      return;
    }

    try {
      setCreating(true);
      const participantIds = selectedUsers.map(user => user.id);
      const res = await api.post('/chats', {
        participantIds,
        name: groupName,
        isGroup: true
      });

      window.location.href = `/chats/${res.data.id}`;
    } catch (error) {
      alert(error.response?.data?.message || 'Erreur lors de la création du groupe');
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl max-h-[85vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-200 bg-slate-50">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-2xl bg-blue-600 text-white flex items-center justify-center text-lg shadow-sm">
              <FiUsers />
            </div>
            <div>
              <h2 className="text-xl font-semibold text-slate-900">Créer un groupe</h2>
              <p className="text-sm text-slate-500">Sélectionnez des membres et définissez un nom pour votre groupe.</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 transition-colors"
          >
            <FiX size={22} />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={createGroupChat} className="p-6 space-y-5 overflow-y-auto">
          <div className="grid gap-5">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Nom du groupe</label>
              <input
                type="text"
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                placeholder="Entrez le nom du groupe..."
                className="w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Ajouter des membres</label>
              <div className="relative">
                <FiSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  placeholder="Rechercher des utilisateurs..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 pl-12 text-slate-900 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                />
              </div>
            </div>
          </div>

          {selectedUsers.length > 0 && (
            <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4">
              <div className="flex items-center justify-between mb-3">
                <span className="text-sm font-semibold text-slate-700">Membres sélectionnés ({selectedUsers.length})</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {selectedUsers.map((user) => (
                  <div
                    key={user.id}
                    className="flex items-center gap-2 rounded-full bg-blue-100 px-3 py-2 text-sm text-blue-900"
                  >
                    <span>{user.fullName}</span>
                    <button
                      type="button"
                      onClick={() => toggleUserSelection(user)}
                      className="rounded-full p-1 text-blue-600 hover:bg-blue-200"
                    >
                      <FiX size={14} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="rounded-[1.5rem] border border-slate-200 bg-white shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-200 bg-slate-50">
              <p className="text-sm font-semibold text-slate-700">Choisissez les participants</p>
            </div>
            <div className="max-h-64 overflow-y-auto">
              {loading ? (
                <div className="space-y-3 p-4">
                  {[1, 2, 3, 4, 5].map((i) => (
                    <div key={i} className="animate-pulse">
                      <div className="flex items-center gap-3 p-3">
                        <div className="w-10 h-10 rounded-full bg-slate-200"></div>
                        <div className="flex-1 space-y-2">
                          <div className="h-4 rounded bg-slate-200 w-3/4"></div>
                          <div className="h-3 rounded bg-slate-200 w-1/2"></div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : filteredUsers.length === 0 ? (
                <div className="text-center py-10 text-slate-500">{searchTerm ? 'Aucun utilisateur trouvé' : 'Aucun utilisateur disponible'}</div>
              ) : (
                <div className="divide-y divide-slate-200">
                  {filteredUsers.map((user) => {
                    const isSelected = selectedUsers.some(u => u.id === user.id);
                    return (
                      <button
                        key={user.id}
                        type="button"
                        onClick={() => toggleUserSelection(user)}
                        className={`w-full px-5 py-4 text-left transition-colors ${isSelected ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                      >
                        <div className="flex items-center justify-between gap-4">
                          <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-sm font-semibold ${isSelected ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-700'}`}>
                              {user.fullName.charAt(0).toUpperCase()}
                            </div>
                            <div>
                              <p className="font-medium text-slate-900">{user.fullName}</p>
                              <p className="text-sm text-slate-500">{user.email}</p>
                            </div>
                          </div>
                          {isSelected && (
                            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-blue-600 text-white">
                              <FiCheck size={16} />
                            </div>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          <div className="flex flex-col gap-3 sm:flex-row sm:justify-end">
            <button
              type="button"
              onClick={onClose}
              className="w-full sm:w-auto rounded-2xl border border-slate-300 bg-slate-100 px-5 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-200 transition-colors"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={creating || !groupName.trim() || selectedUsers.length === 0}
              className="w-full sm:w-auto rounded-2xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white hover:bg-blue-700 disabled:bg-slate-300 disabled:text-slate-500 transition-colors flex items-center justify-center gap-2"
            >
              {creating ? (
                <>
                  <FiLoader className="animate-spin" size={16} />
                  Création...
                </>
              ) : (
                <>
                  <FiPlus size={16} />
                  Créer le groupe
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default GroupChat;
